$("authForm").addEventListener("submit",async e=>{e.preventDefault();if(!sb)return toast("Configure a URL e a chave pública do Supabase em app.js.");const email=$("authEmail").value.trim(),password=$("authPassword").value;let r;if(authMode==="signup"){r=await sb.auth.signUp({email,password,options:{data:{full_name:$("authName").value.trim()}}});if(!r.error&&!r.data.session){toast("Conta criada. Confirme seu e-mail e depois entre.");return}}else r=await sb.auth.signInWithPassword({email,password});if(r.error)return toast(r.error.message);await boot(r.data.user)});
