function updateHeaderClock(){const now=new Date(),h=now.getHours();const greeting=h<12?'Bom dia':h<18?'Boa tarde':'Boa noite';const date=now.toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});const time=now.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});const name=(profile?.full_name||user?.user_metadata?.full_name||user?.email?.split('@')[0]||'').trim().split(/\s+/)[0];const el=$('todayLabel');if(el)el.innerHTML=`<div class="greeting-line"><span class="greeting">${greeting}${name?`, ${esc(name)}`:''}!</span></div><div class="datetime-line"><span class="clock-date">${date}</span><span class="live-clock"><span class="clock-symbol">◷</span>${time}</span></div>`;}
setInterval(()=>{if(user)updateHeaderClock()},1000);
async function boot(u){user=u;$("authView").classList.add("hidden");$("appView").classList.remove("hidden");$("userEmail").textContent=u.email;$("avatar").textContent=(u.user_metadata?.full_name||u.email||"U").slice(0,1).toUpperCase();$("userName").textContent=u.user_metadata?.full_name||u.email.split("@")[0];updateHeaderClock();$("connectionStatus").textContent="Carregando dados…";await loadData();$("connectionStatus").textContent="Conectado ao Supabase";goPage(currentPage)}
async function loadData(){if(!sb||!user)return;const [p,t,b,g]=await Promise.all([sb.from("profiles").select("*").eq("id",user.id).maybeSingle(),sb.from("transactions").select("*").order("transaction_date",{ascending:false}),sb.from("recurring_bills").select("*").order("due_date"),sb.from("goals").select("*").order("created_at",{ascending:false})]);for(const r of [p,t,b,g])if(r.error){console.error(r.error);toast("Erro ao carregar dados: "+r.error.message);return}profile=p.data||{id:user.id,full_name:user.user_metadata?.full_name||"",salary_amount:0,payday:30,current_balance:0,reserve_amount:0,plan:"free"};transactions=t.data||[];bills=b.data||[];goals=g.data||[];const iv=await sb.from("investments").select("*").order("investment_date",{ascending:false});if(!iv.error)investments=iv.data||[];if(!p.data){const ins=await sb.from("profiles").upsert({id:user.id,full_name:profile.full_name,email:user.email});if(ins.error)console.error(ins.error)}}
function paidTransactions(){return transactions.filter(t=>t.is_paid)}
function monthTransactions(){const m=today().slice(0,7);return transactions.filter(t=>(t.transaction_date||"").startsWith(m))}
function sums(){const mt=monthTransactions(),income=mt.filter(t=>t.kind==="income"&&t.is_paid).reduce((s,t)=>s+Number(t.amount),0),expense=mt.filter(t=>t.kind==="expense"&&t.is_paid).reduce((s,t)=>s+Number(t.amount),0),openBills=bills.filter(b=>b.is_active&&b.due_date>=today()).reduce((s,b)=>s+Number(b.amount),0);const balance=Number(profile.current_balance||0),available=balance-openBills-Number(profile.reserve_amount||0);const days=Math.max(1,daysToPayday());return {income,expense,openBills,balance,available,perDay:Math.max(0,available/days)}}
function daysToPayday(){const day=Math.min(31,Math.max(1,Number(profile.payday)||30)),now=new Date(),next=new Date(now.getFullYear(),now.getMonth(),day);if(next<=now)next.setMonth(next.getMonth()+1);return Math.max(1,Math.ceil((next-now)/86400000))}
function renderPage(){const c=$("pageContent");if(!user)return;if(currentPage==="dashboard")c.innerHTML=dashboardHTML();else if(currentPage==="transactions")c.innerHTML=transactionsHTML();else if(currentPage==="bills")c.innerHTML=billsHTML();else if(currentPage==="goals")c.innerHTML=goalsHTML();else if(currentPage==="reports")c.innerHTML=reportsHTML();else if(currentPage==="family")c.innerHTML=familyHTML();else c.innerHTML=settingsHTML();bindPageActions()}
function dashboardHTML(){const s=sums(),monthIncome=monthTransactions().filter(t=>t.kind==="income"&&t.is_paid).reduce((a,t)=>a+Number(t.amount),0),monthExpense=monthTransactions().filter(t=>t.kind==="expense"&&t.is_paid).reduce((a,t)=>a+Number(t.amount),0),overdue=bills.filter(b=>b.is_active&&b.due_date<today()).length,healthScore=Math.max(0,Math.min(100,Math.round((monthIncome>0?Math.max(0,Math.min(1,(monthIncome-monthExpense)/monthIncome))*60:20)+(Number(profile.reserve_amount||0)>0?20:0)+(overdue===0?20:Math.max(0,20-overdue*5))))),healthLabel=healthScore>=80?"Boa saúde financeira":healthScore>=55?"Atenção ao orçamento":"Revise suas despesas",upcoming=bills.filter(b=>b.is_active).sort((a,b)=>a.due_date.localeCompare(b.due_date)).slice(0,5),recent=transactions.slice(0,5);return `<div class="grid stats"><div class="stat-card"><div class="stat-top">Disponível por dia <span class="stat-icon">↗</span></div><div class="stat-value positive">${money(s.perDay)}</div><div class="stat-foot">Previsão até o próximo salário</div></div><div class="stat-card"><div class="stat-top">Saldo informado <span class="stat-icon">◉</span></div><div class="stat-value">${money(s.balance)}</div><div class="stat-foot">Atualize nas configurações</div></div><div class="stat-card"><div class="stat-top">Despesas pagas no mês <span class="stat-icon">↘</span></div><div class="stat-value negative">${money(s.expense)}</div><div class="stat-foot">Despesas registradas como pagas</div></div><div class="stat-card"><div class="stat-top">Contas futuras <span class="stat-icon">▦</span></div><div class="stat-value">${money(s.openBills)}</div><div class="stat-foot">Contas ativas cadastradas</div></div><div class="stat-card health-score-card"><div class="stat-top">Saúde financeira <span class="stat-icon">✦</span></div><div class="stat-value">${healthScore}<small>/100</small></div><div class="stat-foot">${healthLabel} · ${overdue} conta(s) vencida(s)</div></div></div><div class="grid dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h3>Previsão até o próximo salário</h3><p>Uma estimativa com os dados que você cadastrou.</p></div><span class="pill">5º dia útil + dia 20</span></div><div class="salary-row"><div><small>Saldo menos contas futuras e reserva</small><strong>${money(s.available)}</strong></div><div class="stat-icon">⌁</div></div><div class="progress"><span style="width:${Math.max(0,Math.min(100,s.balance?100*(Math.max(0,s.available)/s.balance):0))}%"></span></div><div class="salary-info"><div><span>Receitas do mês</span><b class="positive">${money(s.income)}</b></div><div><span>Despesas do mês</span><b class="negative">${money(s.expense)}</b></div><div><span>Estimativa diária</span><b>${money(s.perDay)}</b></div></div><p class="muted small">Estimativa simplificada: mantenha saldo, contas e reserva atualizados. Não é uma consulta bancária nem garantia de saldo real.</p></section><section class="panel"><div class="panel-head"><div><h3>Últimos lançamentos</h3><p>Movimentações recentes da sua conta.</p></div><button class="text-btn" data-go="transactions">Ver todos →</button></div>${recent.length?`<div class="list">${recent.map(transactionRow).join("")}</div>`:empty("Nenhum lançamento ainda","Registre seu primeiro gasto ou receita.")}</section></div><div><section class="panel"><div class="panel-head"><div><h3>Próximas contas</h3><p>Não deixe vencimentos passarem.</p></div><button class="text-btn" data-go="bills">Ver todas →</button></div>${upcoming.length?`<div class="list">${upcoming.map(billRow).join("")}</div>`:empty("Tudo tranquilo por aqui","Cadastre aluguel, internet, parcelas e outras contas.")}<button class="btn outline full" data-action="new-bill">＋ Adicionar conta</button></section><section class="panel"><div class="panel-head"><div><h3>Suas metas</h3><p>Pequenos passos, grandes objetivos.</p></div><button class="text-btn" data-go="goals">Ver metas →</button></div>${goals.slice(0,3).map(g=>`<div class="list-row"><div class="list-icon">◎</div><div class="list-detail"><b>${esc(g.name)}</b><small>${money(g.saved_amount)} de ${money(g.target_amount)}</small><div class="progress" style="margin-top:7px"><span style="width:${Math.min(100,100*Number(g.saved_amount)/Math.max(1,Number(g.target_amount)))}%"></span></div></div></div>`).join("")||empty("Nenhuma meta criada","Defina um objetivo para começar.")}</section></div></div>`}
function empty(title,desc){return `<div class="empty"><b>${title}</b>${desc}</div>`}
function transactionRow(t){return `<div class="list-row"><div class="list-icon">${t.kind==="income"?"↗":"↘"}</div><div class="list-detail"><b>${esc(t.description)}</b><small>${esc(t.category||"Outros")} · ${dateBR(t.transaction_date)} · ${t.is_paid?"Pago":"Pendente"}</small></div><div class="list-amount ${t.kind==="income"?"positive":"negative"}">${t.kind==="income"?"+":"−"} ${money(t.amount)}</div></div>`}
function billRow(b){return `<div class="list-row"><div class="list-icon">▦</div><div class="list-detail"><b>${esc(b.name)}</b><small>Vence ${dateBR(b.due_date)} · ${b.frequency==="monthly"?"Mensal":b.frequency==="weekly"?"Semanal":"Única"}</small></div><div class="list-amount">${money(b.amount)}</div></div>`}
function transactionsHTML(){return `<div class="page-intro"><div><h3>Seus lançamentos</h3><p>Registre receitas e despesas para entender seu mês.</p></div><button class="btn primary" data-action="new-tx">＋ Novo lançamento</button></div><section class="panel"><div class="section-actions" style="margin-bottom:15px"><input id="txSearch" placeholder="Buscar descrição…"><select id="txFilter"><option value="all">Todos os tipos</option><option value="expense">Despesas</option><option value="income">Receitas</option></select><select id="txPaidFilter"><option value="all">Pagos e pendentes</option><option value="paid">Pagos</option><option value="pending">Pendentes</option></select></div><div id="txTable">${txTable(transactions)}</div></section>`}
function txTable(rows){if(!rows.length)return empty("Nenhum lançamento encontrado","Use o botão Novo lançamento para adicionar.");return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Descrição</th><th>Categoria</th><th>Data</th><th>Valor</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(t=>`<tr><td><b>${esc(t.description)}</b><br><span class="muted">${t.kind==="income"?"Receita":"Despesa"}</span></td><td>${esc(t.category||"Outros")}</td><td>${dateBR(t.transaction_date)}</td><td class="${t.kind==="income"?"positive":"negative"}">${money(t.amount)}</td><td><span class="pill ${t.is_paid?"":"pending"}">${t.is_paid?"Pago":"Pendente"}</span></td><td><div class="actions">${familyOwnerId?`<button class="mini-btn" data-share-tx="${t.id}">Compartilhar</button>`:""}<button class="mini-btn" data-edit-tx="${t.id}">Editar</button><button class="mini-btn" data-toggle-tx="${t.id}">${t.is_paid?"Reabrir":"Marcar pago"}</button><button class="mini-btn danger" data-delete-tx="${t.id}">Excluir</button></div></td></tr>`).join("")}</tbody></table></div>`}
function billsHTML(){return `<div class="page-intro"><div><h3>Contas e parcelas</h3><p>Organize vencimentos e despesas recorrentes.</p></div><button class="btn primary" data-action="new-bill">＋ Nova conta</button></div><div class="grid stats"><div class="stat-card"><div class="stat-top">Contas ativas</div><div class="stat-value">${bills.filter(b=>b.is_active).length}</div></div><div class="stat-card"><div class="stat-top">Valor cadastrado</div><div class="stat-value">${money(bills.filter(b=>b.is_active).reduce((s,b)=>s+Number(b.amount),0))}</div></div><div class="stat-card"><div class="stat-top">Parcelas</div><div class="stat-value">${bills.filter(b=>b.bill_type==="installment"&&b.is_active).length}</div></div><div class="stat-card"><div class="stat-top">Vencendo em 7 dias</div><div class="stat-value">${bills.filter(b=>b.is_active&&b.due_date>=today()&&b.due_date<=addDays(today(),7)).length}</div></div></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Conta</th><th>Categoria</th><th>Vencimento</th><th>Repetição</th><th>Valor</th><th>Status</th><th>Ações</th></tr></thead><tbody>${bills.map(b=>`<tr><td><b>${esc(b.name)}</b><br><span class="muted">${b.bill_type==="installment"?"Parcela":"Conta"}</span></td><td>${esc(b.category||"Outros")}</td><td>${dateBR(b.due_date)}</td><td>${b.frequency==="monthly"?"Mensal":b.frequency==="weekly"?"Semanal":"Única"}</td><td>${money(b.amount)}</td><td><span class="pill ${b.is_active?"":"inactive"}">${b.is_active?"Ativa":"Inativa"}</span></td><td><div class="actions"><button class="mini-btn" data-edit-bill="${b.id}">Editar</button><button class="mini-btn" data-pay-bill="${b.id}">Pagar</button>${familyOwnerId?`<button class="mini-btn" data-share-bill="${b.id}">Compartilhar</button>`:""}<button class="mini-btn danger" data-delete-bill="${b.id}">Excluir</button></div></td></tr>`).join("")}</tbody></table></div>${bills.length?"":empty("Nenhuma conta cadastrada","Adicione suas contas fixas e parcelas.")}</section>`}
function addDays(d,n){const x=new Date(d+"T12:00:00");x.setDate(x.getDate()+n);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,"0")}-${String(x.getDate()).padStart(2,"0")}`}
function monthKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`}
function fifthBusinessDay(year,monthIndex){let d=new Date(year,monthIndex,1),count=0;while(count<5){if(d.getDay()!==0&&d.getDay()!==6)count++;if(count<5)d.setDate(d.getDate()+1)}return d}
function projectedSalaryForMonth(year,monthIndex){const total=Math.max(0,Number(profile.salary_amount)||0),day20=profile.receives_salary_day20===true?Math.min(total,Math.max(0,Number(profile.salary_day20_amount??(total*.4))||0)):0,fifth=Math.max(0,total-day20),fifthDate=fifthBusinessDay(year,monthIndex),twentieth=new Date(year,monthIndex,20),now=new Date();return {total,fifth,day20,fifthDate,twentieth}}
function goalsHTML(){return `<div class="page-intro"><div><h3>Metas financeiras</h3><p>Defina objetivos e acompanhe seu progresso.</p></div><button class="btn primary" data-action="new-goal">＋ Nova meta</button></div><div class="grid goal-grid">${goals.map(g=>{const pct=Math.min(100,100*Number(g.saved_amount)/Math.max(1,Number(g.target_amount)));return `<section class="panel goal-card"><div class="list-icon">◎</div><h3>${esc(g.name)}</h3><div class="amount">${money(g.saved_amount)}</div><div class="sub">de ${money(g.target_amount)} · ${Math.round(pct)}% concluído</div><div class="progress"><span style="width:${pct}%"></span></div><div class="goal-foot"><span>${g.target_date?"Meta: "+dateBR(g.target_date):"Sem prazo definido"}</span><span>${money(Math.max(0,g.target_amount-g.saved_amount))} restantes</span></div><div class="actions" style="margin-top:14px"><button class="mini-btn" data-add-goal="${g.id}">＋ Guardar</button><button class="mini-btn" data-edit-goal="${g.id}">Editar</button><button class="mini-btn danger" data-delete-goal="${g.id}">Excluir</button></div></section>`}).join("")}</div>${goals.length?"":`<section class="panel">${empty("Sua primeira meta começa aqui","Crie uma meta para reserva de emergência, viagem ou compra importante.")}</section>`}`}
function reportsHTML(){const selected=window.reportMonth||today().slice(0,7),all=transactions.filter(t=>(t.transaction_date||"").startsWith(selected)),inc=all.filter(t=>t.kind==="income").reduce((s,t)=>s+Number(t.amount),0),exp=all.filter(t=>t.kind==="expense").reduce((s,t)=>s+Number(t.amount),0),paidExp=all.filter(t=>t.kind==="expense"&&t.is_paid).reduce((s,t)=>s+Number(t.amount),0),pending=all.filter(t=>t.kind==='expense'&&!t.is_paid).reduce((s,t)=>s+Number(t.amount),0),cats={};all.filter(t=>t.kind==="expense").forEach(t=>cats[t.category||"Outros"]=(cats[t.category||"Outros"]||0)+Number(t.amount));const max=Math.max(1,...Object.values(cats));const opts=Array.from({length:12},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);const v=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;return `<option value="${v}" ${v===selected?'selected':''}>${d.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</option>`}).join('');const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;const a=transactions.filter(t=>(t.transaction_date||'').startsWith(key));return {label:d.toLocaleDateString('pt-BR',{month:'short'}),income:a.filter(t=>t.kind==='income').reduce((s,t)=>s+Number(t.amount),0),expense:a.filter(t=>t.kind==='expense').reduce((s,t)=>s+Number(t.amount),0)}});const trendMax=Math.max(1,...months.flatMap(m=>[m.income,m.expense]));return `<div class="page-intro report-intro"><div><h3>Relatórios financeiros</h3><p>Uma visão clara do seu dinheiro, com comparativos e indicadores do período.</p></div><div class="report-controls"><label>Período<select id="reportMonth">${opts}</select></label><button class="btn primary" data-action="export">↓ Exportar CSV</button></div></div><div class="grid stats report-stats"><div class="stat-card report-income"><div class="stat-top">Receitas no período</div><div class="stat-value positive">${money(inc)}</div><div class="stat-foot">${all.filter(t=>t.kind==='income').length} registros</div></div><div class="stat-card report-expense"><div class="stat-top">Despesas no período</div><div class="stat-value negative">${money(exp)}</div><div class="stat-foot">${all.filter(t=>t.kind==='expense').length} registros</div></div><div class="stat-card"><div class="stat-top">Saldo do período</div><div class="stat-value ${inc-exp>=0?'positive':'negative'}">${money(inc-exp)}</div><div class="stat-foot">Receitas menos despesas</div></div><div class="stat-card"><div class="stat-top">Despesas pendentes</div><div class="stat-value">${money(pending)}</div><div class="stat-foot">Despesas ainda não marcadas como pagas</div></div></div><section class="panel budget-panel"><div class="panel-head"><div><h3>Orçamento por categoria</h3><p>Defina limites mensais e acompanhe quanto já foi consumido no período selecionado.</p></div></div><form id="categoryBudgetForm"><div class="budget-grid">${["Alimentação","Moradia","Transporte","Saúde","Lazer","Educação","Contas","Cartão","Combustível","Assinaturas","Outros"].map(cat=>{const spent=Number(cats[cat]||0),limit=Number((profile.category_budgets||{})[cat]||0),pct=limit>0?Math.min(100,spent/limit*100):0;return `<label class="budget-item"><span class="budget-title">${esc(cat)}</span><span class="budget-spent">${money(spent)} <small>gastos</small></span><input type="number" min="0" step="0.01" name="budget:${esc(cat)}" value="${limit||''}" placeholder="Limite mensal R$"><span class="budget-track"><i style="width:${pct}%;background:${limit>0&&spent>limit?'#e45d70':'#16b99a'}"></i></span><small class="${limit>0&&spent>limit?'negative':'muted'}">${limit>0?(spent>limit?'Limite excedido em '+money(spent-limit):'Restam '+money(limit-spent)):'Sem limite definido'}</small></label>`}).join('')}</div><div class="modal-actions"><span class="muted small">Limites são salvos na sua conta e sincronizam entre dispositivos.</span><button class="btn primary" type="submit">Salvar orçamento</button></div></form></section><section class="panel report-trend"><div class="panel-head"><div><h3>Comparativo dos últimos 6 meses</h3><p>Receitas e despesas registradas em cada mês.</p></div><div class="legend"><span><i class="legend-income"></i>Receitas</span><span><i class="legend-expense"></i>Despesas</span></div></div><div class="trend-chart">${months.map(m=>`<div class="trend-col"><div class="trend-bars"><span class="trend-bar income" title="Receitas: ${money(m.income)}" style="height:${Math.max(m.income?3:0,m.income/trendMax*100)}%"></span><span class="trend-bar expense" title="Despesas: ${money(m.expense)}" style="height:${Math.max(m.expense?3:0,m.expense/trendMax*100)}%"></span></div><small>${esc(m.label)}</small></div>`).join('')}</div></section><div class="grid report-grid"><section class="panel"><div class="panel-head"><div><h3>Despesas por categoria</h3><p>Distribuição dos gastos do período selecionado.</p></div></div>${Object.keys(cats).length?Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="bar-row"><span>${esc(k)}</span><div class="bar-track"><span style="width:${v/max*100}%"></span></div><b>${money(v)}</b></div>`).join(""):`${empty("Sem despesas neste período","Quando houver lançamentos, a distribuição aparecerá aqui.")}`}<div class="report-total"><span>Total de despesas</span><b>${money(exp)}</b></div></section><section class="panel"><div class="panel-head"><div><h3>Resumo de pagamentos</h3><p>Status dos lançamentos no período selecionado.</p></div></div><div class="report-summary-row"><span><i class="status-dot paid-dot"></i>Despesas pagas</span><b>${money(paidExp)}</b></div><div class="report-summary-row"><span><i class="status-dot pending-dot"></i>Valores pendentes</span><b>${money(pending)}</b></div><div class="report-summary-row"><span>Quantidade de lançamentos</span><b>${all.length}</b></div><div class="report-summary-row"><span>Resultado do período</span><b class="${inc-exp>=0?'positive':'negative'}">${money(inc-exp)}</b></div><p class="muted small report-note">Relatórios calculados com base nos lançamentos cadastrados. Confira se os valores e o status de pagamento estão atualizados.</p></section></div>`}
function familyHTML(){const code=profile.family_code||"Ainda não criado",inGroup=!!familyOwnerId,month=window.familyMonth||today().slice(0,7),monthRows=familyTransactions.filter(t=>(t.transaction_date||"").startsWith(month)),income=monthRows.filter(t=>t.kind==="income").reduce((a,t)=>a+Number(t.amount),0),expense=monthRows.filter(t=>t.kind==="expense").reduce((a,t)=>a+Number(t.amount),0),sharedTotal=familyTransactions.filter(t=>t.kind==="expense").reduce((a,t)=>a+Number(t.amount),0),cats={};monthRows.filter(t=>t.kind==="expense").forEach(t=>cats[t.category||"Outros"]=(cats[t.category||"Outros"]||0)+Number(t.amount));const max=Math.max(1,...Object.values(cats));const months=Array.from({length:12},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);const v=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;return `<option value="${v}" ${v===month?"selected":""}>${d.toLocaleDateString("pt-BR",{month:"long",year:"numeric"})}</option>`}).join("");return `<div class="page-intro"><div><h3>Espaço da família</h3><p>Organize despesas, receitas e compromissos compartilhados. Seus dados pessoais continuam privados.</p></div><button class="btn outline" data-action="refresh-family">↻ Atualizar</button></div><section class="panel"><div class="panel-head"><div><h3>${inGroup?"Grupo familiar ativo":"Seu grupo familiar"}</h3><p class="muted small">${inGroup?"Lançamentos compartilhados ficam visíveis a todos os integrantes.":"Crie um grupo ou entre usando o código gerado por outro integrante."}</p></div><span class="pill">${inGroup?"Conectado":"Não conectado"}</span></div>${profile.family_code?`<p class="muted small">Código para convidar integrantes</p><div class="family-code">${esc(code)}</div><button class="btn outline" data-action="copy-family-code">Copiar código</button>`:inGroup?`<p class="muted small">Você está conectado ao grupo de outro integrante. Peça ao responsável o código para convidar novas pessoas.</p>`:`<div class="section-actions"><button class="btn primary" data-action="create-family">Criar grupo familiar</button><input id="joinCode" placeholder="Cole o código do grupo"><button class="btn outline" data-action="join-family">Entrar em grupo</button></div>`}</section>${inGroup?`<div class="family-summary-head"><div><h3>Resumo familiar</h3><p>Indicadores das movimentações compartilhadas.</p></div><label>Período<select id="familyMonth">${months}</select></label></div><div class="grid stats family-summary-stats"><div class="stat-card"><div class="stat-top">Receitas da família</div><div class="stat-value positive">${money(income)}</div><div class="stat-foot">${monthRows.filter(t=>t.kind==="income").length} registros no período</div></div><div class="stat-card"><div class="stat-top">Despesas da família</div><div class="stat-value negative">${money(expense)}</div><div class="stat-foot">${monthRows.filter(t=>t.kind==="expense").length} registros no período</div></div><div class="stat-card"><div class="stat-top">Resultado do período</div><div class="stat-value ${income-expense>=0?"positive":"negative"}">${money(income-expense)}</div><div class="stat-foot">Receitas menos despesas</div></div><div class="stat-card"><div class="stat-top">Lançamentos compartilhados</div><div class="stat-value">${monthRows.length}</div><div class="stat-foot">${familyMembers.length} integrante(s) no grupo</div></div></div><div class="grid family-detail-grid"><section class="panel"><div class="panel-head"><div><h3>Despesas por categoria</h3><p>Distribuição no período selecionado.</p></div></div>${Object.keys(cats).length?Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="bar-row"><span>${esc(k)}</span><div class="bar-track"><span style="width:${v/max*100}%"></span></div><b>${money(v)}</b></div>`).join(""):`<p class="muted small">Ainda não há despesas nesse período.</p>`}</section><section class="panel"><div class="panel-head"><div><h3>Movimentações por integrante</h3><p>Quem registrou as movimentações do período.</p></div></div>${familyMembers.map(m=>{const own=monthRows.filter(t=>t.created_by===m.id),out=own.filter(t=>t.kind==="expense").reduce((a,t)=>a+Number(t.amount),0),inc=own.filter(t=>t.kind==="income").reduce((a,t)=>a+Number(t.amount),0);return `<div class="family-member-summary"><div><b>${esc(m.full_name||m.email||"Integrante")}</b><small>${own.length} lançamento(s)</small></div><div><span class="negative">−${money(out)}</span><span class="positive">+${money(inc)}</span></div></div>`}).join("")}</section></div><section class="panel"><div class="panel-head"><div><h3>Adicionar movimentação compartilhada</h3><p>Use para despesas e receitas da família, como mercado, aluguel, contas, contribuições e reembolsos.</p></div></div><form id="familyTxForm" class="form-grid"><label>Descrição<input id="familyTxDescription" required maxlength="120" placeholder="Ex.: compra do mercado"></label><label>Categoria<select id="familyTxCategory"><option>Alimentação</option><option>Moradia</option><option>Transporte</option><option>Saúde</option><option>Contas</option><option>Educação</option><option>Lazer</option><option>Cartão</option><option>Assinaturas</option><option>Outros</option></select></label><label>Valor (R$)<input id="familyTxAmount" required type="number" min="0.01" step="0.01" placeholder="0,00"></label><label>Data<input id="familyTxDate" required type="date" value="${today()}"></label><label>Tipo<select id="familyTxKind"><option value="expense">Despesa</option><option value="income">Receita</option></select></label><label>Quem registrou<input value="${esc(profile.full_name||user?.email||"Você")}" disabled></label><label style="grid-column:1/-1">Observações (opcional)<input id="familyTxNotes" maxlength="500" placeholder="Detalhes para os integrantes"></label><div class="modal-actions" style="grid-column:1/-1"><button class="btn primary" type="submit">＋ Salvar no livro da família</button></div></form></section><section class="panel"><div class="panel-head"><div><h3>Livro financeiro da família</h3><p>Histórico de todas as movimentações compartilhadas.</p></div><span class="pill">${familyTransactions.length} registros</span></div>${familyTransactions.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Registrado por</th><th>Valor</th><th></th></tr></thead><tbody>${familyTransactions.map(t=>`<tr><td>${dateBR(t.transaction_date)}</td><td><b>${esc(t.description)}</b>${t.notes?`<small class="table-note">${esc(t.notes)}</small>`:""}</td><td>${esc(t.category||"Outros")}</td><td>${esc(t.creator_name||"Integrante")}</td><td class="${t.kind==="income"?"positive":"negative"}">${t.kind==="income"?"+":"−"}${money(t.amount)}</td><td>${t.created_by===user.id?`<button class="mini-btn danger" data-delete-family-tx="${t.id}">Excluir</button>`:""}</td></tr>`).join("")}</tbody></table></div>`:empty("Ainda não há movimentações compartilhadas","Você pode lançar aqui ou marcar ‘Compartilhar com a família’ ao cadastrar uma movimentação pessoal.")}</section>`:`<section class="panel">${empty("Conecte-se ao grupo do seu pai","Para compartilhar despesas, uma conta precisa criar o grupo e a outra deve entrar usando o código. Depois, cadastros compartilhados aparecerão para ambos.")}</section>`}<section class="panel"><div class="panel-head"><h3>Integrantes</h3><span class="pill">${familyMembers.length} membros</span></div>${familyMembers.map(m=>`<div class="list-row"><div class="avatar">${esc((m.full_name||m.email||"U").slice(0,1).toUpperCase())}</div><div class="list-detail"><b>${esc(m.full_name||"Integrante")}${m.id===user.id?" (você)":""}</b><small>${esc(m.email||"")}</small></div></div>`).join("")||empty("Nenhum integrante carregado","Crie um grupo ou entre usando um código.")}</section>${inGroup?`<section class="panel family-danger-zone"><h3>Gerenciar grupo</h3><p>Você pode sair deste grupo ou encerrar o grupo que criou.</p><button class="btn danger" data-action="leave-family">Sair / encerrar grupo</button></section>`:""}<div class="notice-card">Privacidade: somente registros marcados/feitos como compartilhados aparecem aqui. Salário, cartões, abastecimentos e lançamentos pessoais não são expostos automaticamente.</div>`}
function bindPageActions(){document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>goPage(b.dataset.go));document.querySelectorAll("[data-action]").forEach(b=>b.onclick=()=>{const a=b.dataset.action;if(a==="new-tx")openTransaction();if(a==="new-bill")openBill();if(a==="new-goal")openGoal();if(a==="export")exportCSV();if(a==="export-backup")exportFullBackup();if(a==="create-family")createFamily();if(a==="join-family")joinFamily();if(a==="copy-family-code")GenCopyFamilyCode();if(a==="refresh-family"){loadFamily().then(renderPage)}if(a==="leave-family")leaveFamily()});document.querySelectorAll("[data-delete-family-tx]").forEach(b=>b.onclick=()=>deleteFamilyTransaction(b.dataset.deleteFamilyTx));document.querySelectorAll("[data-share-tx]").forEach(b=>b.onclick=()=>shareExistingTransaction(b.dataset.shareTx));document.querySelectorAll("[data-share-bill]").forEach(b=>b.onclick=()=>shareExistingBill(b.dataset.shareBill));const familyForm=$("familyTxForm");if(familyForm)familyForm.onsubmit=saveFamilyTransaction;document.querySelectorAll("[data-edit-tx]").forEach(b=>b.onclick=()=>openTransaction(transactions.find(t=>t.id===b.dataset.editTx)));document.querySelectorAll("[data-delete-tx]").forEach(b=>b.onclick=()=>removeRow("transactions",b.dataset.deleteTx));document.querySelectorAll("[data-toggle-tx]").forEach(b=>b.onclick=()=>toggleTransaction(b.dataset.toggleTx));document.querySelectorAll("[data-edit-bill]").forEach(b=>b.onclick=()=>openBill(bills.find(x=>x.id===b.dataset.editBill)));document.querySelectorAll("[data-delete-bill]").forEach(b=>b.onclick=()=>removeRow("recurring_bills",b.dataset.deleteBill));document.querySelectorAll("[data-pay-bill]").forEach(b=>b.onclick=()=>payBill(b.dataset.payBill));document.querySelectorAll("[data-edit-goal]").forEach(b=>b.onclick=()=>openGoal(goals.find(x=>x.id===b.dataset.editGoal)));document.querySelectorAll("[data-delete-goal]").forEach(b=>b.onclick=()=>removeRow("goals",b.dataset.deleteGoal));document.querySelectorAll("[data-add-goal]").forEach(b=>b.onclick=()=>addToGoal(b.dataset.addGoal));const search=$("txSearch"),filter=$("txFilter"),paid=$("txPaidFilter");if(search)for(const el of [search,filter,paid])el.oninput=()=>{let rows=transactions.filter(t=>t.description.toLowerCase().includes(search.value.toLowerCase()));if(filter.value!=="all")rows=rows.filter(t=>t.kind===filter.value);if(paid.value!=="all")rows=rows.filter(t=>paid.value==="paid"?t.is_paid:!t.is_paid);$("txTable").innerHTML=txTable(rows);bindPageActions()};const reportMonth=$("reportMonth");if(reportMonth)reportMonth.onchange=()=>{window.reportMonth=reportMonth.value;renderPage()};const familyMonth=$("familyMonth");if(familyMonth)familyMonth.onchange=()=>{window.familyMonth=familyMonth.value;renderPage()};const bf=$("categoryBudgetForm");if(bf)bf.onsubmit=saveCategoryBudgets;const sf=$("settingsForm");if(sf){sf.onsubmit=saveSettings;const salaryInput=$("setSalary"),receive20=$("setReceives20"),amount20=$("setSalary20"),wrap20=$("setSalary20Wrap"),hint20=$("salary20Hint");let amount20Manual=false;if(amount20)amount20.oninput=()=>{amount20Manual=true};const update20=()=>{const on=!!receive20?.checked;wrap20?.classList.toggle("hidden",!on);hint20?.classList.toggle("hidden",!on);if(on&&amount20&&!amount20Manual)amount20.value=(Math.max(0,Number(salaryInput?.value)||0)*.4).toFixed(2)};if(receive20)receive20.onchange=()=>{amount20Manual=false;update20()};if(salaryInput)salaryInput.oninput=()=>{if(!amount20Manual&&receive20?.checked&&amount20)amount20.value=(Math.max(0,Number(salaryInput.value)||0)*.4).toFixed(2);if(hint20)hint20.innerHTML=`Sugestão padrão: 40% do salário (${money((Number(salaryInput?.value)||0)*.4)}). Você pode alterar o valor manualmente.`};update20()}}
function openTransaction(t=null){$("transactionForm").reset();$("transactionId").value=t?.id||"";$("txShareFamily").checked=false;$("txShareFamily").disabled=!familyOwnerId||!!t;$("transactionModalTitle").textContent=t?"Editar lançamento":"Novo lançamento";txKind=t?.kind||"expense";document.querySelectorAll("[data-kind]").forEach(b=>b.classList.toggle("selected",b.dataset.kind===txKind));$("txDescription").value=t?.description||"";$("txCategory").value=t?.category||"Alimentação";$("txAmount").value=t?.amount||"";$("txDate").value=t?.transaction_date||today();$("txPaid").checked=t?.is_paid??true;$("txNotes").value=t?.notes||"";$("transactionDialog").showModal()}
$("transactionForm").onsubmit=async e=>{e.preventDefault();const id=$("transactionId").value,payload={user_id:user.id,description:$("txDescription").value.trim(),category:$("txCategory").value,amount:Number($("txAmount").value),transaction_date:$("txDate").value,kind:txKind,is_paid:$("txPaid").checked,notes:$("txNotes").value.trim()};const r=id?await sb.from("transactions").update(payload).eq("id",id):await sb.from("transactions").insert(payload);if(r.error)return toast(r.error.message);let shareWarning="";if(!id&&$("txShareFamily")?.checked&&familyOwnerId){const sr=await sb.from("family_transactions").insert({family_owner_id:familyOwnerId,created_by:user.id,description:payload.description,category:payload.category,amount:payload.amount,transaction_date:payload.transaction_date,kind:payload.kind,notes:payload.notes||"Lançamento compartilhado a partir dos lançamentos pessoais"});if(sr.error)shareWarning=" O lançamento pessoal foi salvo, mas não foi compartilhado: "+sr.error.message;}const shouldShare=!!$("txShareFamily")?.checked;$("transactionDialog").close();await loadData();if(shouldShare)await loadFamily();renderPage();toast("Lançamento salvo."+shareWarning)};
function openBill(b=null){$("billForm").reset();$("billId").value=b?.id||"";$("billShareFamily").checked=false;$("billShareFamily").disabled=!familyOwnerId||!!b;$("billModalTitle").textContent=b?"Editar conta":"Nova conta";$("billName").value=b?.name||"";$("billCategory").value=b?.category||"Contas";$("billAmount").value=b?.amount||"";$("billDue").value=b?.due_date||today();$("billFrequency").value=b?.frequency||"monthly";$("billType").value=b?.bill_type||"bill";$("billActive").checked=b?.is_active??true;$("billDialog").showModal()}
$("billForm").onsubmit=async e=>{e.preventDefault();const id=$("billId").value,p={user_id:user.id,name:$("billName").value.trim(),category:$("billCategory").value,amount:Number($("billAmount").value),due_date:$("billDue").value,frequency:$("billFrequency").value,bill_type:$("billType").value,is_active:$("billActive").checked};const r=id?await sb.from("recurring_bills").update(p).eq("id",id):await sb.from("recurring_bills").insert(p);if(r.error)return toast(r.error.message);let shareWarning="";if(!id&&$("billShareFamily")?.checked&&familyOwnerId){const sr=await sb.from("family_transactions").insert({family_owner_id:familyOwnerId,created_by:user.id,description:"Conta: "+p.name,category:p.category,amount:p.amount,transaction_date:p.due_date,kind:"expense",notes:"Conta cadastrada no módulo Contas · "+(p.frequency==="monthly"?"recorrência mensal":p.frequency==="weekly"?"recorrência semanal":"pagamento único")});if(sr.error)shareWarning=" A conta pessoal foi salva, mas não foi compartilhada: "+sr.error.message;}const shouldShare=!!$("billShareFamily")?.checked;$("billDialog").close();await loadData();if(shouldShare)await loadFamily();renderPage();toast("Conta salva."+shareWarning)};
function openGoal(g=null){$("goalForm").reset();$("goalId").value=g?.id||"";$("goalModalTitle").textContent=g?"Editar meta":"Nova meta";$("goalName").value=g?.name||"";$("goalTarget").value=g?.target_amount||"";$("goalSaved").value=g?.saved_amount||0;$("goalDate").value=g?.target_date||"";$("goalDialog").showModal()}
$("goalForm").onsubmit=async e=>{e.preventDefault();const id=$("goalId").value,p={user_id:user.id,name:$("goalName").value.trim(),target_amount:Number($("goalTarget").value),saved_amount:Number($("goalSaved").value)||0,target_date:$("goalDate").value||null};const r=id?await sb.from("goals").update(p).eq("id",id):await sb.from("goals").insert(p);if(r.error)return toast(r.error.message);$("goalDialog").close();await loadData();renderPage();toast("Meta salva.")};
async function removeRow(table,id){if(!confirm("Tem certeza que deseja excluir este registro?"))return;const r=await sb.from(table).delete().eq("id",id);if(r.error)return toast(r.error.message);await loadData();renderPage();toast("Registro excluído.")}
async function toggleTransaction(id){const t=transactions.find(x=>x.id===id);const r=await sb.from("transactions").update({is_paid:!t.is_paid}).eq("id",id);if(r.error)return toast(r.error.message);await loadData();renderPage()}
async function payBill(id){const b=bills.find(x=>x.id===id);const r=await sb.from("transactions").insert({user_id:user.id,description:b.name,category:b.category||"Contas",amount:b.amount,transaction_date:today(),kind:"expense",is_paid:true,notes:"Gerado ao marcar conta como paga"});if(r.error)return toast(r.error.message);if(b.frequency==="once"){await sb.from("recurring_bills").update({is_active:false}).eq("id",id)}else{const d=new Date(b.due_date+"T12:00:00");if(b.frequency==="weekly")d.setDate(d.getDate()+7);else d.setMonth(d.getMonth()+1);await sb.from("recurring_bills").update({due_date:d.toLocaleDateString("en-CA")}).eq("id",id)}await loadData();renderPage();toast("Pagamento registrado e conta atualizada.")}
async function addToGoal(id){const g=goals.find(x=>x.id===id),raw=prompt("Quanto deseja adicionar à meta?", "50");if(raw===null)return;const amount=Number(raw.replace(",","."));if(!(amount>0))return toast("Informe um valor válido.");const r=await sb.from("goals").update({saved_amount:Number(g.saved_amount)+amount}).eq("id",id);if(r.error)return toast(r.error.message);await loadData();renderPage();toast("Meta atualizada.")}
function settingsHTML(){const salary=Math.max(0,Number(profile.salary_amount)||0),enabled=profile.receives_salary_day20===true,amount=Number(profile.salary_day20_amount??(salary*.4))||0;return `<div class="page-intro"><div><h3>Configurações pessoais</h3><p>Configure salário, vale do dia 20, saldo atual e reserva. Essas informações ficam privadas na sua conta.</p></div></div><section class="panel"><div class="panel-head"><div><h3>Perfil e planejamento salarial</h3><p>Os valores ajudam a calcular suas previsões; não são consultados automaticamente no banco.</p></div></div><form id="settingsForm" class="form-grid settings-form"><label>Nome<input id="setName" maxlength="100" value="${esc(profile.full_name||user?.user_metadata?.full_name||'')}" placeholder="Seu nome"></label><label>Salário mensal (R$)<input id="setSalary" type="number" min="0" step="0.01" value="${salary||''}" placeholder="Ex.: 3000,00"></label><label class="checkline settings-day20-toggle"><input id="setReceives20" type="checkbox" ${enabled?'checked':''}> Recebo vale/adiantamento no dia 20</label><label id="setSalary20Wrap" class="${enabled?'':'hidden'}">Valor do vale do dia 20 (R$)<input id="setSalary20" type="number" min="0" step="0.01" value="${enabled?(amount||salary*.4).toFixed(2):((salary*.4)||0).toFixed(2)}" placeholder="40% do salário"></label><div id="salary20Hint" class="notice settings-hint ${enabled?'':'hidden'}" style="grid-column:1/-1">Sugestão padrão: 40% do salário (${money(salary*.4)}). Você pode alterar o valor manualmente.</div><label>Saldo disponível atual (R$)<input id="setBalance" type="number" min="0" step="0.01" value="${Number(profile.current_balance)||0}" placeholder="0,00"></label><label>Reserva que deseja manter (R$)<input id="setReserve" type="number" min="0" step="0.01" value="${Number(profile.reserve_amount)||0}" placeholder="0,00"></label><div class="notice" style="grid-column:1/-1">O vale do dia 20 é tratado como parte do salário mensal informado. Ao ativá-lo, o sistema sugere 40% para o dia 20 e considera o restante no pagamento principal.</div><div class="modal-actions" style="grid-column:1/-1"><button class="btn primary" type="submit">Salvar configurações</button></div></form></section><section class="panel"><div class="panel-head"><div><h3>Dados e privacidade</h3><p>Seus lançamentos pessoais não aparecem para outros integrantes sem compartilhamento explícito.</p></div></div><button class="btn outline" data-action="export-backup">↓ Exportar backup dos meus dados</button></section>`}
async function saveSettings(e){e.preventDefault();const salary=Math.max(0,Number($("setSalary").value)||0),receives20=$("setReceives20").checked;let raw20=Number($("setSalary20").value);if(!Number.isFinite(raw20)||raw20<0)raw20=salary*.4;const salary20=receives20?Math.min(salary,Math.max(0,raw20)):0;const p={id:user.id,email:user.email,full_name:$("setName").value.trim(),salary_amount:salary,receives_salary_day20:receives20,salary_day20_amount:salary20,current_balance:Number($("setBalance").value)||0,payday:5,reserve_amount:Number($("setReserve").value)||0};const r=await sb.from("profiles").upsert(p);if(r.error)return toast("Não foi possível salvar as configurações: "+r.error.message+". Confira se executou a atualização SQL V4.8.");profile={...profile,...p};$("userName").textContent=p.full_name||user.email.split("@")[0];await loadData();renderPage();toast("Configurações salvas.")}
async function saveCategoryBudgets(e){e.preventDefault();const form=e.currentTarget,budgets={...(profile.category_budgets||{})};for(const el of form.querySelectorAll("input[name^=\"budget:\"]")){const category=el.name.slice(7),value=Number(el.value)||0;if(value>0)budgets[category]=value;else delete budgets[category]}const {error}=await sb.from("profiles").update({category_budgets:budgets}).eq("id",user.id);if(error)return toast("Não foi possível salvar o orçamento. Confira se executou a migração SQL: "+error.message);profile={...profile,category_budgets:budgets};renderPage();toast("Limites mensais salvos na sua conta.")}
function exportFullBackup(){const backup={product:"Salário Inteligente",format_version:1,exported_at:new Date().toISOString(),account:{id:user?.id,email:user?.email},profile,transactions,bills,goals,credit_cards:typeof creditCards!=="undefined"?creditCards:[],card_purchases:typeof cardPurchases!=="undefined"?cardPurchases:[],vehicles:typeof vehicles!=="undefined"?vehicles:[],fuel_records:typeof fuelRecords!=="undefined"?fuelRecords:[]};const blob=new Blob([JSON.stringify(backup,null,2)],{type:"application/json;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`salario-inteligente-backup-${today()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Backup baixado. Guarde o arquivo em local privado.")}
function exportCSV(){const rows=[["Tipo","Descrição","Categoria","Data","Valor","Pago","Observação"],...transactions.map(t=>[t.kind,t.description,t.category,t.transaction_date,t.amount,t.is_paid?"Sim":"Não",t.notes||""])];const csv=rows.map(r=>r.map(v=>`"${String(v??"").replace(/"/g,'""')}"`).join(";")).join("\r\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8;"}));a.download="salario-inteligente-lancamentos.csv";a.click();URL.revokeObjectURL(a.href)}
function showNotifications(){const due=bills.filter(b=>b.is_active&&b.due_date>=today()&&b.due_date<=addDays(today(),7));alert(due.length?"Contas vencendo nos próximos 7 dias:\n"+due.map(b=>`${b.name}: ${money(b.amount)} — ${dateBR(b.due_date)}`).join("\n"):"Você não tem contas cadastradas vencendo nos próximos 7 dias.");}
function makeCode(){return Math.random().toString(36).slice(2,8).toUpperCase()}
async function createFamily(){if(profile.family_code)return toast("Você já possui um código de grupo.");if(familyOwnerId&&familyOwnerId!==user.id)return toast("Você já participa do grupo de outro integrante. Peça ao responsável para convidar pessoas.");const code=makeCode();const r=await sb.from("profiles").update({family_code:code}).eq("id",user.id);if(r.error)return toast(r.error.message);profile.family_code=code;await loadFamily();renderPage();toast("Grupo criado. Compartilhe o código com seu pai para ele entrar.")}
async function joinFamily(){const code=$("joinCode")?.value.trim().toUpperCase();if(!code)return toast("Digite o código do grupo.");if(profile.family_code)return toast("Sua conta já é responsável por um grupo. Para evitar grupos conflitantes, use uma conta que ainda não tenha criado outro grupo.");const {error}=await sb.rpc("join_family_by_code",{p_code:code});if(error)return toast(error.message);await loadFamily();renderPage();toast("Você entrou no grupo familiar. Agora use o livro compartilhado abaixo.")}
async function leaveFamily(){if(!familyOwnerId)return toast('Você não está em um grupo familiar.');if(!confirm('Sair do grupo familiar? Os lançamentos já compartilhados continuarão no histórico do grupo.'))return;if(familyOwnerId===user.id){const {error}=await sb.from('family_members').delete().eq('family_owner_id',user.id);if(error)return toast('Não foi possível encerrar o grupo: '+error.message);const {error:pe}=await sb.from('profiles').update({family_code:null}).eq('id',user.id);if(pe)return toast(pe.message);profile.family_code=null;}else{const {error}=await sb.from('family_members').delete().eq('family_owner_id',familyOwnerId).eq('member_id',user.id);if(error)return toast('Não foi possível sair do grupo: '+error.message);}await loadFamily();renderPage();toast('Você saiu do grupo familiar.');}
async function loadFamily(){if(!user)return;const {data,error}=await sb.from("family_members").select("member_id,family_owner_id,status").or(`member_id.eq.${user.id},family_owner_id.eq.${user.id}`).eq("status","accepted");if(error){console.warn("Falha ao carregar integrantes da família:",error.message);familyMembers=[];familyTransactions=[];familyOwnerId=profile.family_code?user.id:null;return}const links=data||[];familyOwnerId=profile.family_code?user.id:(links.find(x=>x.member_id===user.id)?.family_owner_id||links.find(x=>x.family_owner_id===user.id)?.family_owner_id||null);const ids=[...new Set([user.id,...links.flatMap(x=>[x.member_id,x.family_owner_id])])];const {data:ps,error:pe}=await sb.from("profiles").select("id,full_name,email").in("id",ids);if(pe)console.warn("Falha ao carregar perfis familiares:",pe.message);familyMembers=(ps||[]).map(p=>({...p}));if(!familyMembers.some(p=>p.id===user.id))familyMembers.unshift({id:user.id,full_name:profile.full_name,email:user.email});if(familyOwnerId){const {data:rows,error:te}=await sb.from("family_transactions").select("id,family_owner_id,created_by,description,category,amount,transaction_date,kind,notes,created_at").eq("family_owner_id",familyOwnerId).order("transaction_date",{ascending:false}).limit(200);if(te){console.warn("Falha ao carregar livro familiar:",te.message);familyTransactions=[];return}const creatorIds=[...new Set((rows||[]).map(r=>r.created_by))];const {data:creators}=creatorIds.length?await sb.from("profiles").select("id,full_name,email").in("id",creatorIds):{data:[]};const names=new Map((creators||[]).map(p=>[p.id,p.full_name||p.email||"Integrante"]));familyTransactions=(rows||[]).map(r=>({...r,creator_name:names.get(r.created_by)||"Integrante"}));}else familyTransactions=[]}
async function saveFamilyTransaction(e){e.preventDefault();const form=e.currentTarget;if(!familyOwnerId)return toast("Entre em um grupo familiar primeiro.");const payload={family_owner_id:familyOwnerId,created_by:user.id,description:$("familyTxDescription").value.trim(),category:$("familyTxCategory").value,amount:Number($("familyTxAmount").value),transaction_date:$("familyTxDate").value,kind:$("familyTxKind").value,notes:$("familyTxNotes").value.trim()||null};if(!payload.description||!(payload.amount>0)||!payload.transaction_date)return toast("Confira descrição, valor e data.");const {error}=await sb.from("family_transactions").insert(payload);if(error)return toast("Não foi possível salvar. Confira se executou a migração SQL: "+error.message);form.reset();await loadFamily();renderPage();toast("Movimentação compartilhada com o grupo.")}

async function shareExistingTransaction(id){const t=transactions.find(x=>x.id===id);if(!t||!familyOwnerId)return toast("Entre em um grupo familiar primeiro.");const desc=t.description;const {data:found,error:checkError}=await sb.from("family_transactions").select("id").eq("family_owner_id",familyOwnerId).eq("created_by",user.id).eq("description",desc).eq("amount",t.amount).eq("transaction_date",t.transaction_date).eq("kind",t.kind).limit(1);if(checkError)return toast("Não foi possível verificar duplicidade: "+checkError.message);if(found?.length)return toast("Esse lançamento já parece estar compartilhado.");const {error}=await sb.from("family_transactions").insert({family_owner_id:familyOwnerId,created_by:user.id,description:desc,category:t.category||"Outros",amount:Number(t.amount),transaction_date:t.transaction_date,kind:t.kind,notes:t.notes||"Compartilhado a partir de um lançamento pessoal"});if(error)return toast("Falha ao compartilhar: "+error.message);await loadFamily();renderPage();toast("Lançamento compartilhado com a família.")}
async function shareExistingBill(id){const b=bills.find(x=>x.id===id);if(!b||!familyOwnerId)return toast("Entre em um grupo familiar primeiro.");const desc="Conta: "+b.name;const {data:found,error:checkError}=await sb.from("family_transactions").select("id").eq("family_owner_id",familyOwnerId).eq("created_by",user.id).eq("description",desc).eq("amount",b.amount).eq("transaction_date",b.due_date).eq("kind","expense").limit(1);if(checkError)return toast("Não foi possível verificar duplicidade: "+checkError.message);if(found?.length)return toast("Essa conta já parece estar compartilhada.");const {error}=await sb.from("family_transactions").insert({family_owner_id:familyOwnerId,created_by:user.id,description:desc,category:b.category||"Contas",amount:Number(b.amount),transaction_date:b.due_date,kind:"expense",notes:"Conta cadastrada no módulo Contas · "+(b.frequency==="monthly"?"recorrência mensal":b.frequency==="weekly"?"recorrência semanal":"pagamento único")});if(error)return toast("Falha ao compartilhar: "+error.message);await loadFamily();renderPage();toast("Conta compartilhada com a família.")}
async function deleteFamilyTransaction(id){if(!confirm("Excluir esta movimentação compartilhada? Ela deixará de aparecer para todos os integrantes."))return;const {error}=await sb.from("family_transactions").delete().eq("id",id);if(error)return toast(error.message);await loadFamily();renderPage();toast("Movimentação compartilhada excluída.")}
function GenCopyFamilyCode(){if(!profile.family_code)return toast("Crie um grupo primeiro.");if(navigator.clipboard?.writeText)navigator.clipboard.writeText(profile.family_code).then(()=>toast("Código copiado.")).catch(()=>prompt("Copie o código do grupo:",profile.family_code));else prompt("Copie o código do grupo:",profile.family_code)}
const originalLoadData=loadData;loadData=async function(){await originalLoadData();await loadFamily().catch(()=>{})};
if(sb){sb.auth.getSession().then(({data})=>{if(data.session)boot(data.session.user)});sb.auth.onAuthStateChange((_event,session)=>{if(session?.user&&!user)boot(session.user)})}

/* ===== Upgrade 2.0: cartões, análise de impacto e planejamento futuro ===== */
let creditCards=[], cardPurchases=[];
const baseLoadData=loadData;
loadData=async function(){await baseLoadData();if(!sb||!user)return;const [cr,pr]=await Promise.all([sb.from('credit_cards').select('*').order('created_at',{ascending:false}),sb.from('card_purchases').select('*').order('purchase_date',{ascending:false})]);if(cr.error||pr.error){console.warn('Cartões ainda não configurados no Supabase. Execute a atualização SQL.',cr.error||pr.error);creditCards=[];cardPurchases=[];return}creditCards=cr.data||[];cardPurchases=pr.data||[]};
const baseRenderPage=renderPage;
renderPage=function(){const c=$('pageContent');if(!user)return;if(currentPage==='cards')c.innerHTML=cardsHTML();else if(currentPage==='planning')c.innerHTML=planningHTML();else if(currentPage==='reports')c.innerHTML=enhancedReportsHTML();else baseRenderPage();bindPageActions()};
const baseGoPage=goPage;
goPage=function(page){currentPage=page;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const names={dashboard:'Visão geral',transactions:'Lançamentos',bills:'Contas e parcelas',cards:'Cartões de crédito',planning:'Planejamento futuro',goals:'Metas',reports:'Resumo financeiro',family:'Família',settings:'Configurações',plans:'Planos'};$('pageTitle').textContent=names[page]||'Visão geral';renderPage()};
function cardsHTML(){const active=creditCards.filter(c=>c.is_active!==false),total=active.reduce((s,c)=>s+Number(c.limit_amount||0),0),purchases=cardPurchases.filter(p=>p.status!=='cancelled'),future=purchases.reduce((s,p)=>s+Number(p.installment_amount||0)*Math.max(0,Number(p.installments_total)-Number(p.installments_paid||0)),0);return `<div class="page-intro"><div><h3>Cartões e compras parceladas</h3><p>Acompanhe limites, parcelas futuras e o peso das compras no seu orçamento.</p></div><button class="btn primary" data-action="new-card">＋ Adicionar cartão</button></div><div class="grid stats"><div class="stat-card"><div class="stat-top">Cartões cadastrados</div><div class="stat-value">${active.length}</div><div class="stat-foot">Seus cartões ativos</div></div><div class="stat-card"><div class="stat-top">Limite total</div><div class="stat-value">${money(total)}</div><div class="stat-foot">Limites informados por você</div></div><div class="stat-card"><div class="stat-top">Parcelas futuras</div><div class="stat-value">${money(future)}</div><div class="stat-foot">Saldo restante das compras cadastradas</div></div><div class="stat-card"><div class="stat-top">Compras cadastradas</div><div class="stat-value">${purchases.length}</div><div class="stat-foot">Não consulta a operadora do cartão</div></div></div><section class="panel"><div class="panel-head"><div><h3>Meus cartões</h3><p>Informe limite e dias de fechamento/vencimento para organizar o planejamento.</p></div></div>${active.length?`<div class="grid card-grid">${active.map(c=>`<article class="credit-card"><div class="credit-card-top"><span>◈ ${esc(c.name)}</span><span class="card-brand-badge">${brandLabel(c.brand||'Visa')}</span></div><div class="credit-card-sub">${esc(c.issuer||'Emissor não informado')} · •••• ${esc(c.last_four||'----')}</div><div class="credit-limit-label">Limite informado</div><div class="credit-limit">${money(c.limit_amount)}</div><div class="credit-card-bottom"><span>Fecha dia ${Number(c.closing_day)||'—'}</span><span>Vence dia ${Number(c.due_day)||'—'}</span></div><div class="card-rate">Juros mensais informados: <b>${Number(c.monthly_interest_rate||0).toLocaleString('pt-BR',{maximumFractionDigits:2})}%</b></div><div class="actions"><button class="mini-btn" data-new-purchase="${c.id}">＋ Compra parcelada</button><button class="mini-btn danger" data-delete-card="${c.id}">Excluir</button></div></article>`).join('')}</div>`:empty('Cadastre seu primeiro cartão','Você poderá registrar compras parceladas e ver o impacto das parcelas nos próximos meses.')}<form id="cardForm" class="inline-form hidden"><h3>Novo cartão</h3><div class="form-grid"><label>Nome do cartão<input id="cardName" required placeholder="Ex.: Nubank"></label><label>Bandeira<select id="cardBrand"><option value="Visa">Visa</option><option value="Mastercard">Mastercard</option><option value="Elo">Elo</option><option value="AmericanExpress">American Express</option><option value="Hipercard">Hipercard</option><option value="Other">Outra</option></select><span class="card-brand-preview" id="cardBrandPreview">VISA</span></label><label>Banco / emissor<input id="cardIssuer" placeholder="Ex.: Nubank, Itaú, Inter"></label><label>Últimos 4 dígitos (opcional)<input id="cardLastFour" maxlength="4" inputmode="numeric" placeholder="1234"></label><label>Limite total (R$)<input id="cardLimit" type="number" min="0" step=".01" required></label><label>Dia de fechamento<input id="cardClosing" type="number" min="1" max="31" value="5" required></label><label>Dia de vencimento<input id="cardDue" type="number" min="1" max="31" value="12" required></label><label>Juros mensais do emissor (%)<input id="cardRate" type="number" min="0" step="0.01" value="0" placeholder="Consulte seu contrato"></label></div><p class="muted small">A bandeira identifica a rede do cartão. Juros e tarifas são definidos pelo banco/emissor e pelo tipo de operação; não existe uma taxa única automática por bandeira.</p><div class="modal-actions"><button type="button" class="btn outline" data-action="cancel-card">Cancelar</button><button class="btn primary">Salvar cartão</button></div></form></section><section class="panel"><div class="panel-head"><div><h3>Compras parceladas</h3><p>As parcelas são projetadas nos meses futuros e incluídas nos relatórios.</p></div><button class="btn outline" data-action="new-purchase">＋ Registrar compra</button></div>${purchases.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Compra</th><th>Cartão</th><th>Valor total</th><th>Parcelas</th><th>Parcela mensal</th><th>Data</th><th></th></tr></thead><tbody>${purchases.map(p=>`<tr><td><b>${esc(p.description)}</b><br><span class="muted">${esc(p.category||'Outros')}</span></td><td>${esc(active.find(c=>c.id===p.card_id)?.name||'Cartão removido')}</td><td>${money(p.total_amount)}</td><td>${Number(p.installments_paid||0)}/${p.installments_total}</td><td>${money(p.installment_amount)}</td><td>${dateBR(p.purchase_date)}</td><td><button class="mini-btn danger" data-delete-purchase="${p.id}">Excluir</button></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma compra parcelada','Registre uma compra para projetar as parcelas futuras.')}<div class="notice-card">Importante: informe compras manualmente. O sistema não acessa a operadora nem atualiza automaticamente a fatura real.</div></section>`}
function planningHTML(){const months=[];const now=new Date();for(let i=0;i<6;i++){const d=new Date(now.getFullYear(),now.getMonth()+i,1),key=monthKey(d),label=d.toLocaleDateString('pt-BR',{month:'short',year:'numeric'});const tx=transactions.filter(t=>(t.transaction_date||'').slice(0,7)===key&&!String(t.notes||'').includes('compra_id:')),salaryTx=tx.filter(t=>t.kind==='income'&&/sal[aá]rio/i.test(`${t.description||''} ${t.category||''}`)),otherIncome=tx.filter(t=>t.kind==='income'&&!/sal[aá]rio/i.test(`${t.description||''} ${t.category||''}`)).reduce((s,t)=>s+Number(t.amount),0),salary=projectedSalaryForMonth(d.getFullYear(),d.getMonth()),inc=otherIncome+salary.total,exp=tx.filter(t=>t.kind==='expense').reduce((s,t)=>s+Number(t.amount),0);const billsDue=bills.filter(b=>{if(!b.is_active||!b.due_date||b.due_date>addMonthsDate(key+'-01',1))return false;const due=new Date(b.due_date+'T12:00:00'),start=new Date(d.getFullYear(),d.getMonth(),1);if(due>new Date(d.getFullYear(),d.getMonth()+1,0,23,59,59))return false;return b.frequency==='monthly'?start>=new Date(due.getFullYear(),due.getMonth(),1):b.frequency==='weekly'?start>=new Date(due.getFullYear(),due.getMonth(),1):b.due_date.slice(0,7)===key}).reduce((s,b)=>s+Number(b.amount),0);const installments=cardPurchases.reduce((s,p)=>{const start=new Date((p.purchase_date||today())+'T12:00:00');const offset=(d.getFullYear()-start.getFullYear())*12+d.getMonth()-start.getMonth();return offset>=0&&offset<Number(p.installments_total)-Number(p.installments_paid||0)?s+Number(p.installment_amount):s},0);months.push({label,inc,exp,billsDue,installments,salaryTotal:salary.total,salaryFifth:salary.fifth,salaryDay20:salary.day20,fifthDate:salary.fifthDate,net:inc-exp-billsDue-installments})}const max=Math.max(1,...months.map(m=>Math.abs(m.net)));return `<div class="page-intro"><div><h3>Planejamento dos próximos 6 meses</h3><p>Veja compromissos conhecidos e identifique meses mais apertados antes que cheguem.</p></div><button class="btn outline" data-go="cards">Ver cartões</button></div><div class="notice-card">Projeção estimada com lançamentos futuros, contas recorrentes cadastradas e compras parceladas. Valores não cadastrados não são previstos automaticamente.</div><div class="grid forecast-grid">${months.map((m,i)=>`<section class="panel forecast-card"><div class="forecast-month">${esc(m.label)}</div><div class="forecast-net ${m.net<0?'negative':'positive'}">${money(m.net)}</div><div class="muted small">${m.net<0?'Mês com déficit previsto':m.net===0?'Orçamento equilibrado':'Saldo projetado'}</div><div class="forecast-bar"><span style="width:${Math.max(3,Math.abs(m.net)/max*100)}%;background:${m.net<0?'#d65a67':'#149b7b'}"></span></div><div class="forecast-line"><span>Receitas previstas (inclui salário)</span><b>${money(m.inc)}</b></div><div class="forecast-line"><span>Salário — 5º dia útil (${dateBR(`${m.fifthDate.getFullYear()}-${String(m.fifthDate.getMonth()+1).padStart(2,'0')}-${String(m.fifthDate.getDate()).padStart(2,'0')}`)})</span><b>${money(m.salaryFifth)}</b></div><div class="forecast-line"><span>Salário — dia 20</span><b>${money(m.salaryDay20)}</b></div><div class="forecast-line"><span>Despesas lançadas</span><b>${money(m.exp)}</b></div><div class="forecast-line"><span>Contas cadastradas</span><b>${money(m.billsDue)}</b></div><div class="forecast-line"><span>Parcelas de cartão</span><b>${money(m.installments)}</b></div></section>`).join('')}</div><section class="panel"><div class="panel-head"><div><h3>Próximos compromissos</h3><p>Contas e compras parceladas ativas.</p></div><button class="btn outline" data-go="bills">Gerenciar contas</button></div>${[...bills.filter(b=>b.is_active&&b.due_date>=today()).map(b=>({name:b.name,date:b.due_date,amount:Number(b.amount),type:'Conta'})),...cardPurchases.filter(p=>p.status!=='cancelled').map(p=>({name:p.description,date:addMonthsDate(p.purchase_date,Number(p.installments_paid||0)+1),amount:Number(p.installment_amount),type:'Parcela de cartão'}))].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,10).map(x=>`<div class="list-row"><div class="list-icon">◷</div><div class="list-detail"><b>${esc(x.name)}</b><small>${x.type} · ${dateBR(x.date)}</small></div><div class="list-amount">${money(x.amount)}</div></div>`).join('')||empty('Sem compromissos futuros','Contas e parcelas cadastradas aparecerão aqui.')}</section>`}
function addMonthsDate(date,n){const d=new Date((date||today())+'T12:00:00');d.setMonth(d.getMonth()+n);return d.toLocaleDateString('en-CA')}
function enhancedReportsHTML(){const selected=window.reportMonth||today().slice(0,7),mt=transactions.filter(t=>(t.transaction_date||'').startsWith(selected)),income=mt.filter(t=>t.kind==='income').reduce((s,t)=>s+Number(t.amount),0),expense=mt.filter(t=>t.kind==='expense').reduce((s,t)=>s+Number(t.amount),0),cats={};mt.filter(t=>t.kind==='expense').forEach(t=>cats[t.category||'Outros']=(cats[t.category||'Outros']||0)+Number(t.amount));const total=Math.max(0,expense),entries=Object.entries(cats).sort((a,b)=>b[1]-a[1]),top=entries[0],pct=total?100*top?.[1]/total:0;const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,rows=transactions.filter(t=>(t.transaction_date||'').startsWith(key));return {label:d.toLocaleDateString('pt-BR',{month:'short'}),inc:rows.filter(t=>t.kind==='income').reduce((s,t)=>s+Number(t.amount),0),exp:rows.filter(t=>t.kind==='expense').reduce((s,t)=>s+Number(t.amount),0)}});const max=Math.max(1,...months.flatMap(m=>[m.inc,m.exp]));const opts=Array.from({length:12},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);const v=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;return `<option value="${v}" ${v===selected?'selected':''}>${d.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</option>`}).join('');return `<div class="page-intro report-intro"><div><h3>Relatórios financeiros</h3><p>Receitas, despesas, abastecimentos e categorias em um só lugar.</p></div><div class="report-controls"><label>Período<select id="reportMonth">${opts}</select></label><button class="btn primary" data-action="export">↓ Exportar CSV</button></div></div><div class="grid stats"><div class="stat-card"><div class="stat-top">Receitas do mês</div><div class="stat-value positive">${money(income)}</div><div class="stat-foot">Registros do mês atual</div></div><div class="stat-card"><div class="stat-top">Despesas do mês</div><div class="stat-value negative">${money(expense)}</div><div class="stat-foot">Registros do mês atual</div></div><div class="stat-card"><div class="stat-top">Saldo do mês</div><div class="stat-value ${income-expense<0?'negative':'positive'}">${money(income-expense)}</div><div class="stat-foot">Receitas menos despesas</div></div><div class="stat-card"><div class="stat-top">Da renda comprometida</div><div class="stat-value">${Number(profile.salary_amount)>0?Math.round(expense/Number(profile.salary_amount)*100):0}%</div><div class="stat-foot">Despesas ÷ salário configurado</div></div></div><div class="grid report-grid"><section class="panel"><div class="panel-head"><div><h3>Onde você mais gasta</h3><p>Percentual de cada categoria sobre suas despesas do mês.</p></div></div>${entries.length?entries.map(([name,val])=>{const share=total?val/total*100:0;return `<div class="impact-row"><div class="impact-heading"><b>${esc(name)}</b><strong>${money(val)}</strong></div><div class="bar-track impact-track"><span style="width:${share}%"></span></div><div class="impact-caption"><span>${share.toFixed(1).replace('.',',')}% das despesas</span><span>${Number(profile.salary_amount)>0?(val/Number(profile.salary_amount)*100).toFixed(1).replace('.',','):'—'}% do salário</span></div></div>`}).join(''):empty('Ainda não há dados suficientes','Cadastre despesas para gerar os percentuais.')} ${top?`<div class="insight-box"><b>Principal ponto de atenção: ${esc(top[0])}</b><p>${top[0]} representa ${pct.toFixed(1).replace('.',',')}% de todas as suas despesas neste mês. ${pct>35?'Vale revisar essa categoria e definir um limite mensal.':'Continue acompanhando para perceber mudanças ao longo do tempo.'}</p></div>`:''}</section><section class="panel"><div class="panel-head"><div><h3>Últimos 6 meses</h3><p>Comparação de receitas e despesas registradas.</p></div></div>${months.map(m=>`<div class="month-chart-row"><span>${esc(m.label)}</span><div class="month-bars"><div class="bar-track"><span style="width:${m.inc/max*100}%;background:#159a7a"></span></div><div class="bar-track"><span style="width:${m.exp/max*100}%;background:#df7a84"></span></div></div><div class="month-chart-values"><span>${money(m.inc)}</span><span>${money(m.exp)}</span></div></div>`).join('')}<div class="legend"><span><i class="legend-income"></i> Receitas</span><span><i class="legend-expense"></i> Despesas</span></div></section></div><section class="panel"><div class="panel-head"><div><h3>Leitura prática</h3><p>Indicadores simples para tomar decisões melhores.</p></div></div><div class="grid insight-grid"><div class="insight-tile"><span>Taxa de sobra</span><b>${income>0?Math.max(0,(income-expense)/income*100).toFixed(1).replace('.',','):'0,0'}%</b><small>Parcela das receitas que não foi consumida pelas despesas.</small></div><div class="insight-tile"><span>Gasto médio por lançamento</span><b>${money(mt.filter(t=>t.kind==='expense').length?expense/mt.filter(t=>t.kind==='expense').length:0)}</b><small>Média das despesas registradas no mês.</small></div><div class="insight-tile"><span>Parcelas futuras cadastradas</span><b>${money(cardPurchases.reduce((s,p)=>s+Number(p.installment_amount||0)*Math.max(0,Number(p.installments_total)-Number(p.installments_paid||0)),0))}</b><small>Compromissos futuros informados nos cartões.</small></div></div><p class="muted small">Os resultados dependem dos dados cadastrados manualmente e não substituem extratos bancários.</p></section>`}
const oldBindPageActions=bindPageActions;
bindPageActions=function(){oldBindPageActions();document.querySelectorAll('[data-action="new-card"]').forEach(b=>b.onclick=()=>{$('cardForm')?.classList.remove('hidden');$('cardName')?.focus()});document.querySelectorAll('[data-action="cancel-card"]').forEach(b=>b.onclick=()=> $('cardForm')?.classList.add('hidden'));document.querySelectorAll('[data-action="new-purchase"]').forEach(b=>b.onclick=()=>purchasePrompt());document.querySelectorAll('[data-new-purchase]').forEach(b=>b.onclick=()=>purchasePrompt(b.dataset.newPurchase));document.querySelectorAll('[data-delete-card]').forEach(b=>b.onclick=()=>deleteCard(b.dataset.deleteCard));document.querySelectorAll('[data-delete-purchase]').forEach(b=>b.onclick=()=>deletePurchase(b.dataset.deletePurchase));const cf=$('cardForm');if(cf)cf.onsubmit=saveCard;};
async function saveCard(e){e.preventDefault();const data={user_id:user.id,name:$('cardName').value.trim(),brand:$('cardBrand').value,issuer:$('cardIssuer').value.trim()||null,monthly_interest_rate:Number($('cardRate').value)||0,last_four:$('cardLastFour').value.trim()||null,limit_amount:Number($('cardLimit').value),closing_day:Number($('cardClosing').value),due_day:Number($('cardDue').value),is_active:true};const {error}=await sb.from('credit_cards').insert(data);if(error)return toast(error.message);await loadData();renderPage();toast('Cartão cadastrado!')}
async function purchasePrompt(cardId){if(!creditCards.length)return toast('Cadastre um cartão primeiro.');const opts=creditCards.map((c,i)=>`${i+1}. ${c.name}`).join('\n'),choice=cardId?creditCards.findIndex(c=>c.id===cardId)+1:Number(prompt('Escolha o cartão:\n'+opts,'1'));if(!choice||!creditCards[choice-1])return;const description=prompt('O que você comprou?');if(!description?.trim())return;const total=Number((prompt('Valor total da compra (R$):','600')||'').replace(',','.'));if(!(total>0))return toast('Informe um valor válido.');const installments=Number(prompt('Em quantas parcelas?','6'));if(!Number.isInteger(installments)||installments<1||installments>60)return toast('Informe de 1 a 60 parcelas.');const date=prompt('Data da compra (AAAA-MM-DD):',today())||today(),category=prompt('Categoria (ex.: Eletrônicos, Casa, Saúde):','Outros')||'Outros',card=creditCards[choice-1],monthly=Math.round(total/installments*100)/100;const payload={user_id:user.id,card_id:card.id,description:description.trim(),category,total_amount:total,installments_total:installments,installments_paid:0,installment_amount:monthly,purchase_date:date,status:'active'};const {data,error}=await sb.from('card_purchases').insert(payload).select().single();if(error)return toast(error.message);const txs=[];for(let i=0;i<installments;i++){txs.push({user_id:user.id,description:`${description.trim()} (${i+1}/${installments})`,category,amount:i===installments-1?Math.round((total-monthly*(installments-1))*100)/100:monthly,transaction_date:addMonthsDate(date,i),kind:'expense',is_paid:i===0&&date<=today(),notes:`Cartão: ${card.name} | compra_id:${data.id} | parcela ${i+1}/${installments}`})}const ins=await sb.from('transactions').insert(txs);if(ins.error){await sb.from('card_purchases').delete().eq('id',data.id);return toast('Compra salva parcialmente: '+ins.error.message)}await loadData();renderPage();toast('Compra e parcelas futuras cadastradas.')}
async function deleteCard(id){if(!confirm('Excluir este cartão? As compras já cadastradas serão mantidas no histórico.'))return;const {error}=await sb.from('credit_cards').update({is_active:false}).eq('id',id);if(error)return toast(error.message);await loadData();renderPage();toast('Cartão desativado.')}
