function investmentsHTML(){const total=investments.reduce((a,x)=>a+Number(x.amount||0),0);return `<div class="page-intro"><div><h3>Investimentos</h3></div><span class="pill">Patrimônio informado</span></div><div class="grid stats"><div class="stat-card"><div class="stat-top">Total investido</div><div class="stat-value positive">${money(total)}</div></div><div class="stat-card"><div class="stat-top">Ativos cadastrados</div><div class="stat-value">${investments.length}</div></div></div><section class="panel"><h3>Adicionar investimento</h3><form id="investmentForm" class="form-grid"><label>Nome / ativo<input id="invName" required maxlength="120" placeholder="Ex.: Tesouro Selic"></label><label>Tipo<select id="invType"><option>Reserva de emergência</option><option>Renda fixa</option><option>Ações</option><option>Fundos imobiliários</option><option>ETF</option><option>Criptomoedas</option><option>Previdência</option><option>Outro</option></select></label><label>Valor aplicado (R$)<input id="invAmount" type="number" min="0.01" step="0.01" required></label><label>Data<input id="invDate" type="date" value="${today()}" required></label><label>Instituição (opcional)<input id="invInstitution" maxlength="120" placeholder="Banco ou corretora"></label><label>Observações (opcional)<input id="invNotes" maxlength="300"></label><div class="modal-actions" style="grid-column:1/-1"><button class="btn primary" type="submit">Salvar investimento</button></div></form></section><section class="panel"><h3>Carteira</h3>${investments.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Ativo</th><th>Tipo</th><th>Instituição</th><th>Data</th><th>Valor aplicado</th><th></th></tr></thead><tbody>${investments.map(x=>`<tr><td><b>${esc(x.name)}</b>${x.notes?`<small class="table-note">${esc(x.notes)}</small>`:''}</td><td>${esc(x.investment_type)}</td><td>${esc(x.institution||'—')}</td><td>${dateBR(x.investment_date)}</td><td>${money(x.amount)}</td><td><button class="mini-btn danger" data-delete-investment="${x.id}">Excluir</button></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum investimento cadastrado','Adicione seus investimentos para acompanhar o total aplicado.')}</section><p class="muted small">Valores informados manualmente; não há cotação em tempo real nem recomendação de compra ou venda.</p>`}
async function saveInvestment(e){e.preventDefault();const payload={user_id:user.id,name:$('invName').value.trim(),investment_type:$('invType').value,amount:Number($('invAmount').value),investment_date:$('invDate').value,institution:$('invInstitution').value.trim()||null,notes:$('invNotes').value.trim()||null};const {error}=await sb.from('investments').insert(payload);if(error)return toast('Não foi possível salvar. Execute a atualização SQL incluída no pacote: '+error.message);await loadData();renderPage();toast('Investimento salvo.');}
async function deleteInvestment(id){if(!confirm('Excluir este investimento?'))return;const {error}=await sb.from('investments').delete().eq('id',id);if(error)return toast(error.message);await loadData();renderPage();toast('Investimento excluído.');}
