const goPageV3=goPage;
goPage=async function(page){currentPage=page;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const names={dashboard:'Visão geral',transactions:'Lançamentos',bills:'Contas e parcelas',cards:'Cartões de crédito',fuel:'Abastecimento e veículos',investments:'Investimentos',planning:'Planejamento futuro',goals:'Metas',reports:'Relatórios financeiros',family:'Família',settings:'Configurações',plans:'Planos'};$('pageTitle').textContent=names[page]||'Visão geral';if(page==='family'){await loadFamily()}renderPage()};
function brandLabel(b){return ({Visa:'VISA',Mastercard:'mastercard',Elo:'ELO',AmericanExpress:'AMEX',Hipercard:'HIPERCARD',Other:'OUTRA'})[b]||esc(b||'CARTÃO')}
function fuelHTML(){const active=vehicles.filter(v=>v.is_active!==false),records=fuelRecords.filter(r=>active.some(v=>v.id===r.vehicle_id)),month=today().slice(0,7),monthly=records.filter(r=>(r.fuel_date||'').startsWith(month)),cost=monthly.reduce((s,r)=>s+Number(r.total_amount||0),0),liters=monthly.reduce((s,r)=>s+Number(r.liters||0),0),latest=records[0],vehicleOptions=active.map(v=>`<option value="${v.id}">${esc(v.name)}${v.plate?' · '+esc(v.plate):''}</option>`).join(''),fuelMonths=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);const key=d.toLocaleDateString('en-CA').slice(0,7);return {label:d.toLocaleDateString('pt-BR',{month:'short'}),value:records.filter(r=>(r.fuel_date||'').startsWith(key)).reduce((sum,r)=>sum+Number(r.total_amount||0),0)}}),fuelMax=Math.max(1,...fuelMonths.map(m=>m.value));const vehicleStats=active.map(v=>{const vr=records.filter(r=>r.vehicle_id===v.id).slice().sort((a,b)=>Number(a.odometer)-Number(b.odometer));let previousFull=null,litersSinceFull=0,kmTotal=0,litersTotal=0,intervals=0,lastKmL=null;for(const r of vr){if(previousFull===null){if(r.full_tank){previousFull=r;litersSinceFull=0;}continue;}litersSinceFull+=Number(r.liters||0);if(r.full_tank){const km=Number(r.odometer)-Number(previousFull.odometer);if(km>0&&litersSinceFull>0){lastKmL=km/litersSinceFull;kmTotal+=km;litersTotal+=litersSinceFull;intervals++;}previousFull=r;litersSinceFull=0;}}const spent=vr.reduce((a,r)=>a+Number(r.total_amount||0),0);return {vehicle:v,spent,records:vr.length,kmTotal,litersTotal,avgKmL:litersTotal?kmTotal/litersTotal:null,lastKmL,costKm:kmTotal?spent/kmTotal:null};});const overallKm=vehicleStats.reduce((a,v)=>a+v.kmTotal,0),overallLiters=vehicleStats.reduce((a,v)=>a+v.litersTotal,0),overallSpent=vehicleStats.reduce((a,v)=>a+v.spent,0);const efficiencyRows=vehicleStats.map(st=>`<tr><td><b>${esc(st.vehicle.name)}</b><br><span class="muted">${esc(st.vehicle.model||st.vehicle.fuel_type||'')}</span></td><td>${st.records}</td><td>${st.kmTotal?st.kmTotal.toLocaleString('pt-BR',{maximumFractionDigits:0})+' km':'—'}</td><td>${st.avgKmL?st.avgKmL.toLocaleString('pt-BR',{maximumFractionDigits:2})+' km/L':'Aguardando 2 tanques cheios'}</td><td>${st.lastKmL?st.lastKmL.toLocaleString('pt-BR',{maximumFractionDigits:2})+' km/L':'—'}</td><td>${st.costKm?money(st.costKm)+'/km':'—'}</td><td>${money(st.spent)}</td></tr>`).join('');const rows=records.slice(0,20).map(r=>{const v=active.find(x=>x.id===r.vehicle_id);return `<tr><td>${dateBR(r.fuel_date)}</td><td><b>${esc(v?.name||'Veículo removido')}</b><br><span class="muted">${esc(r.station||r.fuel_name||'')}</span></td><td>${Number(r.odometer).toLocaleString('pt-BR')} km</td><td>${Number(r.liters).toLocaleString('pt-BR',{maximumFractionDigits:3})} L</td><td>${money(r.price_per_liter)}/L</td><td><b>${money(r.total_amount)}</b><br><span class="muted">${esc(r.payment_method||'Não informado')}</span></td><td>${r.full_tank?'Completo':'Parcial'}</td><td><button class="mini-btn" data-edit-fuel="${r.id}">Editar</button><button class="mini-btn danger" data-delete-fuel="${r.id}">Excluir</button></td></tr>`}).join('');return `<div class="hero-strip"><div><div class="eyebrow">CONTROLE DE TRANSPORTE</div><h3>Abastecimento sob controle.</h3><p>Registre veículos, quilometragem, litros e preços para entender o custo real de cada deslocamento.</p></div><div class="hero-mark">⛽</div></div><div class="grid stats"><div class="stat-card"><div class="stat-top">Gasto no mês</div><div class="stat-value negative">${money(cost)}</div><div class="stat-foot">Abastecimentos de ${new Date().toLocaleDateString('pt-BR',{month:'long'})}</div></div><div class="stat-card"><div class="stat-top">Litros no mês</div><div class="stat-value">${liters.toLocaleString('pt-BR',{maximumFractionDigits:1})} L</div><div class="stat-foot">Volume total registrado</div></div><div class="stat-card"><div class="stat-top">Veículos ativos</div><div class="stat-value">${active.length}</div><div class="stat-foot">Veículos cadastrados por você</div></div><div class="stat-card"><div class="stat-top">Último abastecimento</div><div class="stat-value">${latest?money(latest.total_amount):money(0)}</div><div class="stat-foot">${latest?dateBR(latest.fuel_date):'Nenhum registro ainda'}</div></div></div><section class="panel fuel-chart-panel"><div class="panel-head"><div><h3>Gasto com combustível — últimos 6 meses</h3><p>Comparativo mensal com base nos registros cadastrados.</p></div></div><div class="fuel-chart">${fuelMonths.map(m=>`<div class="fuel-chart-col"><div class="fuel-chart-value">${m.value?money(m.value):'—'}</div><div class="fuel-chart-track"><span style="height:${m.value?Math.max(5,m.value/fuelMax*100):2}%"></span></div><small>${esc(m.label)}</small></div>`).join('')}</div></section><section class="panel fuel-efficiency-panel"><div class="panel-head"><div><h3>Relatório de consumo e comparação dos veículos</h3><p>O km/L é calculado entre abastecimentos marcados como tanque cheio; abastecimentos parciais ajudam a compor os litros do intervalo.</p></div><button class="btn outline" data-action="export-fuel">↓ Exportar CSV</button></div><div class="grid stats fuel-efficiency-stats"><div class="stat-card"><div class="stat-top">Distância calculada</div><div class="stat-value">${overallKm.toLocaleString('pt-BR',{maximumFractionDigits:0})} km</div><div class="stat-foot">Intervalos entre tanques cheios</div></div><div class="stat-card"><div class="stat-top">Consumo médio da frota</div><div class="stat-value">${overallLiters? (overallKm/overallLiters).toLocaleString('pt-BR',{maximumFractionDigits:2})+' km/L':'—'}</div><div class="stat-foot">Só com intervalos válidos</div></div><div class="stat-card"><div class="stat-top">Custo médio por km</div><div class="stat-value">${overallKm?money(overallSpent/overallKm):'—'}</div><div class="stat-foot">Gasto acumulado ÷ km calculados</div></div></div>${efficiencyRows?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Veículo</th><th>Registros</th><th>Km calculados</th><th>Média km/L</th><th>Último intervalo</th><th>Custo/km</th><th>Gasto total</th></tr></thead><tbody>${efficiencyRows}</tbody></table></div>`:empty('Sem veículos para comparar','Cadastre um veículo e registre abastecimentos.')}</section><div class="grid fuel-layout"><section class="panel"><div class="panel-head"><div><h3>Registrar abastecimento</h3><p>Informe os dados que aparecem no painel e na nota do posto.</p></div></div>${active.length?`<form id="fuelForm"><div class="form-grid"><label>Veículo<select id="fuelVehicle" required>${vehicleOptions}</select></label><label>Data<input id="fuelDate" type="date" value="${today()}" required></label><label>Quilometragem atual (km)<input id="fuelOdometer" type="number" min="0" step="0.1" required placeholder="Ex.: 125430"></label><label>Combustível<select id="fuelName"><option>Gasolina</option><option>Etanol</option><option>Diesel</option><option>GNV</option><option>Arla 32</option></select></label><label>Litros<input id="fuelLiters" type="number" min="0.001" step="0.001" required placeholder="Ex.: 35,5"></label><label>Preço por litro (R$)<input id="fuelPrice" type="number" min="0" step="0.001" required placeholder="Ex.: 5,89"></label><label>Valor total (R$)<input id="fuelTotal" type="number" min="0" step="0.01" required placeholder="Calculado pelos litros"></label><label>Posto (opcional)<input id="fuelStation" placeholder="Nome do posto"></label><label>Como foi pago?<select id="fuelPayment"><option value="Pix">Pix</option><option value="Crédito">Cartão de crédito</option><option value="Débito">Cartão de débito</option><option value="Dinheiro">Dinheiro</option><option value="Vale combustível">Vale combustível</option><option value="Outro">Outro</option></select></label><label id="fuelInstallmentsWrap" class="hidden">Parcelamento no crédito<select id="fuelInstallments"><option value="1">À vista / 1x</option><option value="2">2x</option><option value="3">3x</option><option value="4">4x</option><option value="5">5x</option><option value="6">6x</option><option value="7">7x</option><option value="8">8x</option><option value="9">9x</option><option value="10">10x</option><option value="11">11x</option><option value="12">12x</option></select></label><label class="checkline"><input id="fuelFull" type="checkbox" checked> Tanque cheio</label><label>Observações<input id="fuelNotes" placeholder="Ex.: viagem, uso urbano"></label></div><div class="fuel-total-preview"><span>Valor estimado</span><b id="fuelPreview">R$ 0,00</b></div><div class="modal-actions"><button class="btn primary" type="submit">Salvar abastecimento</button></div></form>`:empty('Cadastre um veículo primeiro','Use o formulário ao lado para cadastrar carro, moto ou outro veículo.')}</section><section class="panel"><div class="panel-head"><div><h3>Minha garagem</h3><p>Cadastre os veículos que deseja acompanhar.</p></div></div><form id="vehicleForm" class="vehicle-form"><label>Nome para identificar<input id="vehicleName" required placeholder="Ex.: Meu Voyage"></label><label>Modelo (opcional)<input id="vehicleModel" placeholder="Ex.: Volkswagen Voyage 1.0"></label><div class="form-grid"><label>Placa (opcional)<input id="vehiclePlate" maxlength="8" placeholder="ABC1D23"></label><label>Combustível<select id="vehicleFuel"><option>Flex</option><option>Gasolina</option><option>Etanol</option><option>Diesel</option><option>GNV</option><option>Elétrico</option></select></label><label>Capacidade do tanque (L)<input id="vehicleTank" type="number" min="0" step="0.1" placeholder="Ex.: 55"></label><label>Km atual / inicial<input id="vehicleOdometer" type="number" min="0" step="0.1" value="0"></label></div><button class="btn outline full" type="submit">＋ Adicionar veículo</button></form><div class="vehicle-list">${active.map(v=>{const vr=records.filter(r=>r.vehicle_id===v.id),spent=vr.reduce((s,r)=>s+Number(r.total_amount),0);return `<article class="vehicle-item"><div class="vehicle-avatar">${v.fuel_type==='Elétrico'?'⚡':'🚘'}</div><div class="vehicle-info"><b>${esc(v.name)}</b><small>${esc(v.model||v.fuel_type)}${v.plate?' · '+esc(v.plate):''}</small><small>${vr.length} abastecimentos · ${money(spent)} acumulados</small></div><button class="mini-btn" data-edit-vehicle="${v.id}">Editar</button><button class="mini-btn danger" data-delete-vehicle="${v.id}">Remover</button></article>`}).join('')||empty('Garagem vazia','Adicione seu primeiro veículo.')}</div></section></div><section class="panel"><div class="panel-head"><div><h3>Histórico de abastecimentos</h3><p>Últimos 20 registros, com valor, quilometragem e preço por litro.</p></div><button class="btn outline" data-action="export-fuel">↓ Exportar CSV</button></div>${rows?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Veículo / posto</th><th>Odômetro</th><th>Litros</th><th>Preço/L</th><th>Total / pagamento</th><th>Tanque</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('Nenhum abastecimento registrado','Quando você salvar abastecimentos, eles aparecerão aqui.')}</section><div class="notice-card">Dica: para acompanhar consumo (km/L) com mais precisão, informe a quilometragem em todo abastecimento e marque quando completar o tanque. O cálculo entre abastecimentos completos será exibido conforme o histórico crescer.</div>`}
const bindPageActionsV3=bindPageActions;
bindPageActions=function(){bindPageActionsV3();const invf=$('investmentForm');if(invf)invf.onsubmit=saveInvestment;document.querySelectorAll('[data-delete-investment]').forEach(b=>b.onclick=()=>deleteInvestment(b.dataset.deleteInvestment));const rm=$('reportMonth');if(rm)rm.onchange=()=>{window.reportMonth=rm.value;renderPage()};const vf=$('vehicleForm');if(vf)vf.onsubmit=saveVehicle;const ff=$('fuelForm');if(ff)ff.onsubmit=saveFuel;const fp=$('fuelPayment'),fiw=$('fuelInstallmentsWrap');if(fp&&fiw){const toggleInstallments=()=>fiw.classList.toggle('hidden',fp.value!=='Crédito');fp.onchange=toggleInstallments;toggleInstallments()}const liters=$('fuelLiters'),price=$('fuelPrice'),total=$('fuelTotal');const calc=()=>{if(!liters||!price||!total)return;const n=Number(liters.value||0)*Number(price.value||0);if(!total.dataset.manual)total.value=n?n.toFixed(2):'';$('fuelPreview').textContent=money(Number(total.value||n))};if(liters&&price&&total){liters.oninput=()=>{total.dataset.manual='';calc()};price.oninput=()=>{total.dataset.manual='';calc()};total.oninput=()=>{total.dataset.manual='1';$('fuelPreview').textContent=money(Number(total.value||0))}}document.querySelectorAll('[data-edit-fuel]').forEach(b=>b.onclick=()=>editFuel(b.dataset.editFuel));document.querySelectorAll('[data-edit-vehicle]').forEach(b=>b.onclick=()=>editVehicle(b.dataset.editVehicle));document.querySelectorAll('[data-delete-fuel]').forEach(b=>b.onclick=()=>deleteFuel(b.dataset.deleteFuel));document.querySelectorAll('[data-delete-vehicle]').forEach(b=>b.onclick=()=>deleteVehicle(b.dataset.deleteVehicle));document.querySelectorAll('[data-action="export-fuel"]').forEach(b=>b.onclick=exportFuelCSV);const cf=$('cardForm');if(cf){const brand=$('cardBrand');if(brand)brand.onchange=()=>{const logo=$('cardBrandPreview');if(logo)logo.textContent=brandLabel(brand.value)}}};
async function saveVehicle(e){e.preventDefault();const data={user_id:user.id,name:$('vehicleName').value.trim(),model:$('vehicleModel').value.trim()||null,plate:$('vehiclePlate').value.trim().toUpperCase()||null,fuel_type:$('vehicleFuel').value,tank_capacity:Number($('vehicleTank').value)||null,initial_odometer:Number($('vehicleOdometer').value)||0,is_active:true};const {error}=await sb.from('vehicles').insert(data);if(error)return toast(error.message);await loadData();renderPage();toast('Veículo cadastrado com sucesso.')}
async function saveFuel(e){e.preventDefault();const vehicle=vehicles.find(v=>v.id===$('fuelVehicle').value);if(!vehicle)return toast('Selecione um veículo.');const payment=$('fuelPayment')?.value||'Outro',installments=payment==='Crédito'?Math.max(1,Number($('fuelInstallments')?.value||1)):1;const data={user_id:user.id,vehicle_id:vehicle.id,fuel_date:$('fuelDate').value,odometer:Number($('fuelOdometer').value),fuel_name:$('fuelName').value,liters:Number($('fuelLiters').value),price_per_liter:Number($('fuelPrice').value),total_amount:Number($('fuelTotal').value),station:$('fuelStation').value.trim()||null,payment_method:payment,full_tank:$('fuelFull').checked,notes:$('fuelNotes').value.trim()||null};if(!(data.total_amount>0))return toast('Informe um valor total válido.');const latest=fuelRecords.filter(r=>r.vehicle_id===vehicle.id).sort((a,b)=>Number(b.odometer)-Number(a.odometer))[0];if(latest&&data.odometer<Number(latest.odometer))return toast('A quilometragem precisa ser igual ou maior que o último registro desse veículo.');const {data:created,error}=await sb.from('fuel_records').insert(data).select('id').single();if(error)return toast(error.message);const baseDate=new Date(data.fuel_date+'T12:00:00');const installmentAmount=Math.round((data.total_amount/installments)*100)/100;let remaining=Math.round(data.total_amount*100);const txRows=Array.from({length:installments},(_,i)=>{const d=new Date(baseDate);const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+i);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));const date=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const cents=i===installments-1?remaining:Math.round(data.total_amount/installments*100);remaining-=cents;return {user_id:user.id,description:`Abastecimento — ${vehicle.name}${data.station?' · '+data.station:''}${installments>1?` (${i+1}/${installments})`:''}`,category:'Combustível',amount:cents/100,transaction_date:date,kind:'expense',is_paid:i===0,notes:`fuel_record_id:${created.id}; pagamento:${payment}; parcela:${i+1}/${installments}${data.notes?'; '+data.notes:''}`}});const tr=await sb.from('transactions').insert(txRows);if(tr.error){await sb.from('fuel_records').delete().eq('id',created.id);return toast('Não foi possível criar os lançamentos financeiros do abastecimento: '+tr.error.message)}await loadData();renderPage();toast(installments>1?`Abastecimento salvo em ${installments} parcelas e incluído nos relatórios.`:'Abastecimento salvo e incluído nos lançamentos, resumos e relatórios.')}
async function deleteFuel(id){if(!confirm('Excluir este abastecimento e seu lançamento financeiro?'))return;const linked=transactions.filter(t=>String(t.notes||'').includes(`fuel_record_id:${id}`));for(const t of linked){const d=await sb.from('transactions').delete().eq('id',t.id);if(d.error)return toast('Não foi possível remover o lançamento financeiro: '+d.error.message)}const {error}=await sb.from('fuel_records').delete().eq('id',id);if(error)return toast(error.message);await loadData();renderPage();toast('Abastecimento e lançamento financeiro excluídos.')}
async function deleteVehicle(id){if(!confirm('Remover este veículo e seu histórico de abastecimento?'))return;const {error}=await sb.from('vehicles').delete().eq('id',id);if(error)return toast(error.message);await loadData();renderPage();toast('Veículo e histórico removidos.')}
function exportFuelCSV(){const header=['Data','Veículo','Placa','Odômetro km','Combustível','Litros','Preço por litro','Total','Posto','Tanque cheio'];const rows=fuelRecords.map(r=>{const v=vehicles.find(x=>x.id===r.vehicle_id)||{};return [r.fuel_date,v.name||'',v.plate||'',r.odometer,r.fuel_name,r.liters,r.price_per_liter,r.total_amount,r.station||'',r.full_tank?'Sim':'Não']});const csv=[header,...rows].map(row=>row.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}));a.download='abastecimentos.csv';a.click();URL.revokeObjectURL(a.href)}

async function editVehicle(id){const v=vehicles.find(x=>x.id===id);if(!v)return;const name=prompt('Nome para identificar o veículo:',v.name||'');if(name===null)return;if(!name.trim())return toast('Informe um nome para o veículo.');const model=prompt('Modelo:',v.model||'');if(model===null)return;const plate=prompt('Placa:',v.plate||'');if(plate===null)return;const fuel=prompt('Combustível (Flex, Gasolina, Etanol, Diesel, GNV, Elétrico):',v.fuel_type||'Flex');if(fuel===null)return;const tank=prompt('Capacidade do tanque em litros:',v.tank_capacity??'');if(tank===null)return;const odo=prompt('Quilometragem atual/inicial:',v.initial_odometer??0);if(odo===null)return;const {error}=await sb.from('vehicles').update({name:name.trim(),model:model.trim()||null,plate:plate.trim().toUpperCase()||null,fuel_type:fuel.trim()||'Flex',tank_capacity:Number(tank)||null,initial_odometer:Number(odo)||0}).eq('id',id);if(error)return toast(error.message);await loadData();renderPage();toast('Veículo atualizado.')}
async function editFuel(id){const r=fuelRecords.find(x=>x.id===id);if(!r)return;const date=prompt('Data (AAAA-MM-DD):',r.fuel_date||today());if(date===null)return;const odometer=prompt('Quilometragem (km):',r.odometer);if(odometer===null)return;const fuel=prompt('Combustível:',r.fuel_name||'Gasolina');if(fuel===null)return;const liters=prompt('Litros:',r.liters);if(liters===null)return;const price=prompt('Preço por litro (R$):',r.price_per_liter);if(price===null)return;const total=prompt('Valor total (R$):',r.total_amount);if(total===null)return;const station=prompt('Posto:',r.station||'');if(station===null)return;const payment=prompt('Forma de pagamento (Pix, Crédito, Débito, Dinheiro, Vale combustível, Outro):',r.payment_method||'Pix');if(payment===null)return;const full=prompt('Tanque cheio? Digite S para sim ou N para não:',r.full_tank?'S':'N');if(full===null)return;const notes=prompt('Observações:',r.notes||'');if(notes===null)return;const {error}=await sb.from('fuel_records').update({fuel_date:date,odometer:Number(odometer),fuel_name:fuel.trim()||'Gasolina',liters:Number(liters),price_per_liter:Number(price),total_amount:Number(total),station:station.trim()||null,payment_method:payment.trim()||'Outro',full_tank:/^s(im)?$/i.test(full.trim()),notes:notes.trim()||null}).eq('id',id);if(error)return toast(error.message);const linked=transactions.filter(t=>String(t.notes||'').includes(`fuel_record_id:${id}`));if(linked.length){const vehicle=vehicles.find(v=>v.id===r.vehicle_id),count=linked.length,base=new Date(date+'T12:00:00');let cents=Math.round(Number(total)*100);for(let i=0;i<linked.length;i++){const d=new Date(base);const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+i);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));const txDate=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,part=i===linked.length-1?cents:Math.round(Number(total)*100/count);cents-=part;const tx=await sb.from('transactions').update({description:`Abastecimento — ${vehicle?.name||'Veículo'}${station.trim()?' · '+station.trim():''}${count>1?` (${i+1}/${count})`:''}`,amount:part/100,transaction_date:txDate,category:'Combustível',is_paid:i===0,notes:`fuel_record_id:${id}; pagamento:${payment.trim()}; parcela:${i+1}/${count}${notes.trim()?'; '+notes.trim():''}`}).eq('id',linked[i].id);if(tx.error)return toast('Abastecimento atualizado, mas o lançamento financeiro falhou: '+tx.error.message)}}await loadData();renderPage();toast('Abastecimento e lançamento financeiro atualizados.')}

// Tema claro/escuro com preferência persistida neste navegador.
(function setupTheme(){const apply=mode=>{document.documentElement.dataset.theme=mode;localStorage.setItem('salario-theme',mode);const b=document.getElementById('themeToggle');if(b){b.textContent=mode==='dark'?'☀':'☾';b.title=mode==='dark'?'Ativar modo claro':'Ativar modo escuro';b.setAttribute('aria-label',b.title)}};apply(localStorage.getItem('salario-theme')||'light');document.addEventListener('click',e=>{if(e.target.closest('#themeToggle'))apply(document.documentElement.dataset.theme==='dark'?'light':'dark')})})();
